import React, { useMemo, useState } from 'react';
import {
  Box,
  Button,
  Typography,
  Grid,
  CircularProgress,
  Stack,
  Paper,
} from '@mui/material';
import DownloadIcon from '@mui/icons-material/Download';
import PrintIcon from '@mui/icons-material/Print';
import { useReactToPrint } from 'react-to-print';
// eslint-disable-next-line import/no-extraneous-dependencies
import html2canvas from 'html2canvas';
// eslint-disable-next-line import/no-extraneous-dependencies
import jsPDF from 'jspdf';
import { appColors, brandColors, HEADER_GRADIENT } from '../../../theme/appColors';
import { useDailySummanryQuery } from '../../posApi';
import { IDailySummaryData } from '../../../core/Interface/dailySummaryReport.interface';

const CARD_ACCENTS = [
  brandColors.teal,
  brandColors.navy,
  brandColors.mid,
  appColors.carmineRed[100],
  appColors.amberYellow[100],
  appColors.persianBlue[100],
  appColors.forestGreen[100],
  appColors.mulberryPurple[100],
];

interface StatCardProps {
  label: string;
  value: string;
  index: number;
}

const StatCard = ({ label, value, index }: StatCardProps) => {
  const accent = CARD_ACCENTS[index % CARD_ACCENTS.length];
  return (
    <Box
      sx={{
        borderRadius: 1.5,
        borderLeft: `4px solid ${accent}`,
        px: 2,
        py: 1.5,
        background: '#fff',
        boxShadow: '0 1px 4px rgba(0,0,0,0.06)',
        transition: 'box-shadow 0.2s',
        '&:hover': { boxShadow: '0 3px 12px rgba(0,0,0,0.1)' },
        height: '100%',
      }}
    >
      <Typography
        sx={{
          color: '#6b7280',
          fontWeight: 600,
          textTransform: 'uppercase',
          letterSpacing: 0.7,
          fontSize: '0.68rem',
          display: 'block',
          mb: 0.5,
        }}
        variant="caption"
      >
        {label}
      </Typography>
      <Typography
        sx={{ fontWeight: 700, color: accent, fontSize: '1rem', lineHeight: 1.4 }}
        variant="body1"
      >
        {value}
      </Typography>
    </Box>
  );
};

const PrintPage = () => {
  const { data, isLoading } = useDailySummanryQuery({});
  const dailySummaryData = useMemo(() => data?.data as IDailySummaryData, [data]);
  const componentRef = React.useRef<HTMLDivElement | null>(null);
  const [isGeneratingPDF, setIsGeneratingPDF] = useState(false);

  const handlePrint = useReactToPrint({
    content: () => componentRef.current,
    documentTitle: 'Daily Summary Report',
    pageStyle: `
      @page { size: A4; margin: 10mm; }
      body { font-family: 'Arial', sans-serif; margin: 10mm; padding: 0; }
      .print-container { padding: 10px; margin: auto; width: 100%; }
    `,
  });

  const imageToDataURL = (url: string): Promise<string> =>
    new Promise((resolve) => {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        try {
          const canvas = document.createElement('canvas');
          canvas.width = img.width;
          canvas.height = img.height;
          const ctx = canvas.getContext('2d');
          if (ctx) {
            ctx.drawImage(img, 0, 0);
            resolve(canvas.toDataURL('image/png'));
          } else {
            resolve(url);
          }
        } catch (_e) {
          resolve(url);
        }
      };
      img.onerror = () => resolve(url);
      setTimeout(() => { if (!img.complete) resolve(url); }, 10000);
      img.src = url;
    });

  const handleDownloadPDF = async () => {
    if (!componentRef.current || !dailySummaryData) return;
    setIsGeneratingPDF(true);
    try {
      const element = componentRef.current;
      const imgElement = element.querySelector('img') as HTMLImageElement;
      let originalSrc = '';
      if (imgElement && dailySummaryData.logo) {
        originalSrc = imgElement.src;
        try {
          const dataURL = await imageToDataURL(dailySummaryData.logo);
          imgElement.src = dataURL;
          await new Promise((resolve) => setTimeout(resolve, 500));
        } catch (_e) { /* ignore */ }
      }
      const canvas = await html2canvas(element, {
        scale: 2,
        useCORS: false,
        allowTaint: true,
        logging: false,
        backgroundColor: '#ffffff',
      });
      if (imgElement && originalSrc) imgElement.src = originalSrc;
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgWidth = 210;
      const pageHeight = 297;
      const imgHeight = (canvas.height * imgWidth) / canvas.width;
      let heightLeft = imgHeight;
      let position = 0;
      pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight);
      heightLeft -= pageHeight;
      while (heightLeft >= 0) {
        position = heightLeft - imgHeight;
        pdf.addPage();
        pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight);
        heightLeft -= pageHeight;
      }
      pdf.save(`Daily_Summary_Report_${new Date().toISOString().split('T')[0]}.pdf`);
    } catch (error) {
      console.error('Error generating PDF:', error);
    } finally {
      setIsGeneratingPDF(false);
    }
  };

  if (!dailySummaryData || isLoading) return null;

  return (
    <Box sx={{ backgroundColor: brandColors.contentBg, minHeight: '100%', p: { xs: 1.5, sm: 2 } }}>
      {/* Action Toolbar */}
      <Paper
        elevation={0}
        sx={{ borderRadius: 2, mb: 2.5, overflow: 'hidden', boxShadow: '0 2px 12px rgba(15,29,77,0.12)' }}
      >
        <Box
          sx={{
            background: HEADER_GRADIENT,
            px: 3,
            py: 2,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            flexWrap: 'wrap',
            gap: 1,
          }}
        >
          <Box>
            <Typography sx={{ color: '#fff', fontWeight: 700, letterSpacing: 0.3 }} variant="h6">
              Daily Summary Report
            </Typography>
            <Typography sx={{ color: 'rgba(255,255,255,0.72)', fontSize: '0.78rem' }} variant="caption">
              Today's sales and financial overview
            </Typography>
          </Box>
          <Stack direction="row" spacing={1.5}>
            <Button
              disabled={isGeneratingPDF}
              onClick={handleDownloadPDF}
              startIcon={
                isGeneratingPDF
                  ? <CircularProgress size={16} sx={{ color: '#fff' }} />
                  : <DownloadIcon />
              }
              sx={{
                backgroundColor: 'rgba(255,255,255,0.15)',
                color: '#fff',
                border: '1px solid rgba(255,255,255,0.35)',
                borderRadius: 1.5,
                px: 2,
                py: 0.75,
                fontWeight: 600,
                fontSize: '0.82rem',
                textTransform: 'none',
                '&:hover': { backgroundColor: 'rgba(255,255,255,0.25)' },
                '&:disabled': { color: 'rgba(255,255,255,0.45)', borderColor: 'rgba(255,255,255,0.2)' },
              }}
            >
              {isGeneratingPDF ? 'Generating...' : 'Download'}
            </Button>
            <Button
              onClick={handlePrint}
              startIcon={<PrintIcon />}
              sx={{
                backgroundColor: brandColors.teal,
                color: '#fff',
                border: 'none',
                borderRadius: 1.5,
                px: 2,
                py: 0.75,
                fontWeight: 600,
                fontSize: '0.82rem',
                textTransform: 'none',
                '&:hover': { backgroundColor: '#0a7375' },
              }}
            >
              Print
            </Button>
          </Stack>
        </Box>
      </Paper>

      {/* Printable Content */}
      <Paper
        elevation={0}
        sx={{ borderRadius: 2, overflow: 'hidden', boxShadow: '0 1px 8px rgba(0,0,0,0.07)' }}
      >
        <div className="print-container" ref={componentRef}>
          {/* Company Header */}
          <Box
            sx={{
              pt: 4,
              pb: 2.5,
              px: 3,
              textAlign: 'center',
              background: 'linear-gradient(180deg, rgba(15,139,141,0.06) 0%, rgba(255,255,255,0) 100%)',
              borderBottom: '1px solid rgba(15,139,141,0.15)',
            }}
          >
            <img
              alt="Logo"
              src={dailySummaryData.logo}
              style={{
                width: 80,
                height: 80,
                objectFit: 'contain',
                borderRadius: 12,
                marginBottom: 12,
                border: '2px solid rgba(15,139,141,0.2)',
                padding: 4,
                backgroundColor: '#fff',
              }}
            />
            <Typography sx={{ fontWeight: 800, color: brandColors.navy, mb: 0.5 }} variant="h5">
              {dailySummaryData.headerText1}
            </Typography>
            <Typography sx={{ color: '#4b5563', fontSize: '0.88rem', mb: 0.25 }} variant="body2">
              {dailySummaryData.headerText2}
            </Typography>
            <Typography sx={{ color: '#4b5563', fontSize: '0.88rem', mb: 0.25 }} variant="body2">
              {dailySummaryData.headerText3}
            </Typography>
            <Stack direction="row" spacing={3} justifyContent="center" sx={{ mt: 1 }}>
              <Typography sx={{ color: brandColors.teal, fontWeight: 600, fontSize: '0.8rem' }} variant="caption">
                {dailySummaryData.email}
              </Typography>
              <Typography sx={{ color: brandColors.teal, fontWeight: 600, fontSize: '0.8rem' }} variant="caption">
                {dailySummaryData.mobile}
              </Typography>
            </Stack>
          </Box>

          {/* Stats Section */}
          <Box sx={{ p: 3, backgroundColor: '#f9fafb' }}>
            <Typography
              sx={{
                color: '#6b7280',
                fontWeight: 700,
                letterSpacing: 1.2,
                fontSize: '0.7rem',
                display: 'block',
                mb: 2,
                textTransform: 'uppercase',
              }}
              variant="overline"
            >
              Financial Overview
            </Typography>
            <Grid container spacing={2}>
              {Object.entries(dailySummaryData.bodyData).map(([key, value], index) => (
                <Grid item key={key} lg={4} sm={6} xs={12}>
                  <StatCard index={index} label={key} value={value as string} />
                </Grid>
              ))}
            </Grid>
          </Box>
        </div>
      </Paper>
    </Box>
  );
};

export default React.memo(PrintPage);
